from xml.etree import ElementTree as ET

W = '{http://schemas.openxmlformats.org/wordprocessingml/2006/main}'

def para_text(p):
    parts = []
    for node in p.iter():
        tag = node.tag
        if tag == W+'t':
            parts.append(node.text or '')
        elif tag == W+'tab':
            parts.append('\t')
        elif tag == W+'br':
            parts.append('\n')
        elif tag == W+'drawing':
            parts.append('[[IMAGE]]')
    return ''.join(parts)

def style_of(p):
    pPr = p.find(W+'pPr')
    if pPr is None: return ''
    s = pPr.find(W+'pStyle')
    if s is None: return ''
    return s.get(W+'val') or ''

def extract(path, out):
    z = zipfile.ZipFile(path)
    xml = z.read('word/document.xml')
    root = ET.fromstring(xml)
    body = root.find(W+'body')
    lines = []
    def walk(el, depth=0):
        for child in el:
            if child.tag == W+'p':
                st = style_of(child)
                t = para_text(child).strip()
                if not t: continue
                m = re.match(r'Heading(\d)', st)
                if m:
                    lines.append('#'*int(m.group(1)) + ' ' + t)
                elif st.lower().startswith('title'):
                    lines.append('# ' + t)
                elif st.lower().startswith('caption'):
                    lines.append('*' + t + '*')
                else:
                    lines.append(t)
            elif child.tag == W+'tbl':
                lines.append('')
                lines.append('<TABLE>')
                for tr in child.findall(W+'tr'):
                    cells = []
                    for tc in tr.findall(W+'tc'):
                        ct = ' '.join(para_text(p).strip() for p in tc.findall(W+'p'))
                        cells.append(ct.strip())
                    lines.append(' | '.join(cells))
                lines.append('</TABLE>')
                lines.append('')
    walk(body)
    txt = '\n\n'.join(lines)
    txt = re.sub(r'\n{3,}', '\n\n', txt)
    with open(out, 'w', encoding='utf-8') as f:
        f.write(txt)
    print(path, '->', out, len(txt), 'chars')

if __name__ == '__main__':
    extract(sys.argv[1], sys.argv[2])
